// ***************
// Filename: blur_sharpen_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of blur_sharpen: joins the register map
//   blur_sharpen_regs (modport regs) and the logic blur_sharpen (modport
//   core). cfg_* go from the register map to the logic (register values, _wr
//   write pulses, _rd read pulses), sts_* come back (values read, _set / _clr
//   hardware set / clear pulses). A logic block ties every sts_* member it
//   does not use to 0. Generated by ip/scripts/regmap_gen.py from
//   blur_sharpen_regs.json: edit the JSON and regenerate.
// Date: 2026-10-16
interface blur_sharpen_regs_if #(
  parameter int N = 5,
  parameter int COEF_W = 12
) ();
  logic [3-1:0] cfg_mode;
  logic cfg_mode_wr;
  logic [32-1:0] cfg_frame_size;
  logic cfg_frame_size_wr;
  logic [5-1:0] cfg_blur_shift;
  logic cfg_blur_shift_wr;
  logic [5-1:0] cfg_sharp_shift;
  logic cfg_sharp_shift_wr;
  logic [32-1:0] sts_status;
  logic [32-1:0] sts_info;
  logic [(N * N)*(COEF_W)-1:0] cfg_blur_k;
  logic [N * N-1:0] cfg_blur_k_wr;
  logic [(N * N)*(COEF_W)-1:0] cfg_sharp_k;
  logic [N * N-1:0] cfg_sharp_k_wr;

  modport regs (output cfg_mode, cfg_mode_wr, cfg_frame_size, cfg_frame_size_wr, cfg_blur_shift,
    cfg_blur_shift_wr, cfg_sharp_shift, cfg_sharp_shift_wr, cfg_blur_k, cfg_blur_k_wr, cfg_sharp_k,
    cfg_sharp_k_wr, input sts_status, sts_info);
  modport core (output sts_status, sts_info, input cfg_mode, cfg_mode_wr, cfg_frame_size, cfg_frame_size_wr,
    cfg_blur_shift, cfg_blur_shift_wr, cfg_sharp_shift, cfg_sharp_shift_wr, cfg_blur_k, cfg_blur_k_wr,
    cfg_sharp_k, cfg_sharp_k_wr);
  modport monitor (input cfg_mode, cfg_mode_wr, cfg_frame_size, cfg_frame_size_wr, cfg_blur_shift,
    cfg_blur_shift_wr, cfg_sharp_shift, cfg_sharp_shift_wr, cfg_blur_k, cfg_blur_k_wr, cfg_sharp_k,
    cfg_sharp_k_wr, sts_status, sts_info);
endinterface
